func NewFreshnessConfigValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (FreshnessConfigValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing FreshnessConfigValue Attribute Value",
				"While creating a FreshnessConfigValue value, a missing attribute value was detected. "+
					"A FreshnessConfigValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("FreshnessConfigValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid FreshnessConfigValue Attribute Type",
				"While creating a FreshnessConfigValue value, an invalid attribute value was detected. "+
					"A FreshnessConfigValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("FreshnessConfigValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("FreshnessConfigValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra FreshnessConfigValue Attribute Value",
				"While creating a FreshnessConfigValue value, an extra attribute value was detected. "+
					"A FreshnessConfigValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra FreshnessConfigValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewFreshnessConfigValueUnknown(), diags
	}

	if diags.HasError() {
		return NewFreshnessConfigValueUnknown(), diags
	}

	return FreshnessConfigValue{
		state: attr.ValueStateKnown,
	}, diags
}

func NewFreshnessConfigValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) FreshnessConfigValue {
	object, diags := NewFreshnessConfigValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewFreshnessConfigValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t FreshnessConfigType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewFreshnessConfigValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewFreshnessConfigValueUnknown(), nil
	}

	if in.IsNull() {
		return NewFreshnessConfigValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewFreshnessConfigValueMust(FreshnessConfigValue{}.AttributeTypes(ctx), attributes), nil
}

